#!/bin/bash

if [ -d "/data/data/com.termux" ]; then
    TMP="/data/data/com.termux/files/usr/tmp"
    mkdir -p "$TMP"
else
    TMP="/tmp"
fi

# Vérifier les dépendances
if ! command -v base64 &> /dev/null; then
    [ -d "/data/data/com.termux" ] && pkg install -y coreutils
fi

# Décoder et exécuter
echo "" | base64 -d | gunzip > "$TMP/install.sh"
chmod +x "$TMP/install.sh"
bash "$TMP/install.sh"
rm -f "$TMP/install.sh"
